typedef float rational_t;
typedef unsigned int face_ref;

extern "C" float sqrtf(float);

class vector3d
{
public:
  float x, y, z;

  vector3d operator+(const vector3d& b) const
  {
    vector3d r = { x + b.x, y + b.y, z + b.z };
    return r;
  }
  vector3d operator-(const vector3d& b) const
  {
    vector3d r = { x - b.x, y - b.y, z - b.z };
    return r;
  }
  vector3d operator*(float s) const
  {
    vector3d r = { x * s, y * s, z * s };
    return r;
  }
  float xz_length() const
  {
    return sqrtf(x*x + z*z);
  }
};

inline vector3d operator*(float s, const vector3d& v)
{
  return v * s;
}

inline float dot(const vector3d& a, const vector3d& b)
{
  return a.x*b.x + a.y*b.y + a.z*b.z;
}

class vr_pmesh
{
public:
  bool is_cosmetic(face_ref) const;
};

__asm__(".equ is_cosmetic__C8vr_pmeshUi, 0x002D6FC0");

class cface_replacement
{
public:
  bool is_cosmetic() const { return pP->is_cosmetic(rF); }
  const vector3d& get_center() const { return center; }
  rational_t get_radius() const { return radius; }
  const vector3d& get_normal() const { return normal; }

  const vr_pmesh* pP;
  face_ref rF;
  vector3d center;
  rational_t radius;
  vector3d normal;
};

template<class T> class vector
{
public:
  class const_iterator
  {
  public:
    const_iterator() {}
    explicit const_iterator(const T* q) : p(q) {}
    const_iterator operator+(int n) const { return const_iterator(p+n); }
    const_iterator& operator++() { ++p; return *this; }
    bool operator<=(const const_iterator& b) const { return p<=b.p; }
    const T& operator*() const { return *p; }
  private:
    const T* p;
  };

  const_iterator begin() const { return const_iterator(first); }
  T* first;
  T* last;
  T* end_storage;
};

class region
{
public:
  const vector<cface_replacement>& get_sorted() const { return sorted; }
  int get_low_index(float) const;
  int get_high_index(float) const;
private:
  vector<cface_replacement> sorted;
};

__asm__(".equ get_low_index__C6regionf, 0x002E7220");
__asm__(".equ get_high_index__C6regionf, 0x002E7288");

bool collide_polygon_segment(face_ref, const vr_pmesh*,
                             const vector3d&, const vector3d&, vector3d&);
__asm__(".equ collide_polygon_segment__FUiPC8vr_pmeshRC8vector3dT2R8vector3d, 0x002DCAA8");

bool collide_segment_region_with_poly_data( const vector3d& p1, const vector3d& p2,
                                            const region* t,
                                            vector3d& hit_loc, vector3d& hit_normal,
                                            unsigned int ct,
                                            const vector3d& rel_vel,
                                            const vr_pmesh** pM,
                                            face_ref* rF )
{
  //profiler_start_timer(profiler::PTM_SEG_RGN);

  bool hit = false;
  vector3d m1pos = (p1+p2)*0.5F;

  // This is dependant on the USP tree being horizontal!
  rational_t m1rad = (p1-p2).xz_length();

  int low_idx = t->get_low_index( m1pos.x - m1rad );
  if ( low_idx >= 0 )
  {
    int high_idx = t->get_high_index( m1pos.x + m1rad );
    bool first_hit = true;
    vector<cface_replacement>::const_iterator cfi = t->get_sorted().begin() + low_idx;
    vector<cface_replacement>::const_iterator cfi_end = t->get_sorted().begin() + high_idx;
    for ( ; cfi<=cfi_end; ++cfi )
    {
      const cface_replacement& f2 = *cfi;
      if ( !f2.is_cosmetic() )
      {
        rational_t r = f2.get_radius() + m1rad;
        vector3d xz_diff = m1pos - f2.get_center();
        if ( xz_diff.x*xz_diff.x+xz_diff.z*xz_diff.z < r*r )
        {
          // Inside here we know that we're within a radius of a cface in the XZ plane
          vector3d next_hit_loc;
          vector3d next_hit_normal = f2.get_normal();
          rational_t dot_res = dot( next_hit_normal, rel_vel );
          if ( !(ct&2) || dot_res<=0 )
          {
            if ( collide_polygon_segment( f2.rF, f2.pP, p1, p2, next_hit_loc ) )
            {
              if ( first_hit )
              {
                hit_loc = next_hit_loc;
                hit_normal = next_hit_normal;
                first_hit = false;
                // If they want the collision-face we hit (pathfinder) then showandtell
                if ( rF )
                {
                  *pM = f2.pP;
                  *rF = f2.rF;
                }
              }
              else
              {
                if (dot(next_hit_loc,rel_vel)<dot(hit_loc,rel_vel))
                {
                  hit_loc = next_hit_loc;
                  hit_normal = next_hit_normal;
                  // If they want the collision-face we hit (pathfinder) then showandtell
                  if( rF )
                  {
                    *pM = f2.pP;
                    *rF = f2.rF;
                  }
                }
              }
              hit = true;
            }
          }
        }
      }
    }
  }

  //profiler_stop_timer(profiler::PTM_SEG_RGN);

  return hit;
}
